text(await tools.exec_command({cmd:"python - <<'PY'
from sympy import Poly, sympify, symbols
x, y, z = symbols('x y z')
s = '-117968192370600*18**(1/3)/(217603955769048*(24201 + 253*sqrt(9165))**(1/3) + 2273005839412*sqrt(9165)*(24201 + 253*sqrt(9165))**(1/3)) - 15720318185*2**(2/3)*3**(1/3)*(24201 + 253*sqrt(9165))**(2/3)/(217603955769048*(24201 + 253*sqrt(9165))**(1/3) + 2273005839412*sqrt(9165)*(24201 + 253*sqrt(9165))**(1/3)) + 15720318185*12**(1/3)*(24201 + 253*sqrt(9165))**(2/3)/(217603955769048*(24201 + 253*sqrt(9165))**(1/3) + 2273005839412*sqrt(9165)*(24201 + 253*sqrt(9165))**(1/3)) + 117968192370600*2**(1/3)*3**(2/3)/(217603955769048*(24201 + 253*sqrt(9165))**(1/3) + 2273005839412*sqrt(9165)*(24201 + 253*sqrt(9165))**(1/3))'
e = sympify(s)
for gens in [(x,), (x, y), (x, y, z)]:
    f = Poly(e, *gens)
    for convert in [False, True]:
        _, g = f.clear_denoms(convert=convert)
        zero = Poly(0, *gens, domain=g.domain)
        assert g.rep == zero.rep
        assert g.is_zero
        assert g.terms_gcd() == zero.terms_gcd()
        assert g.primitive() == zero.primitive()
    _, g = Poly(e*x + 1, *gens).clear_denoms()
    assert g.degree(x) == 0
print('Issue example: canonical zero, is_zero, terms_gcd, and primitive passed for 1–3 generators; vanishing leading terms also passed.')
